) AS (
  VALUES 
    (482::BIGINT, 'No es un mal profesor, se nota que sabe bastante de mate, solo que hace muy pocos quices, para 25 % hace solo 6 y no deja tareas mientras que otros profes si dejan distintas actividades extra entonces tomelo en cuenta'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '6ed92299b9b2e15555febb4739d2253724d1c4b24dec4f33c97e68900bc76182'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Se nota que el profe conoce bien la materia pero no lo recomendaria para mate general. Sus explicaciones no son las mejores, puede ser algo confuso. Lo que esta super mal es que hace 6 quices y no deja tareas, ent 25% se reparte en esos quices, cada uno vale como 4% y si le va mal cuesta recuperar.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '38727cea89533cd8e26dba92978b95e21b57387f094107c54d2054f30884de25'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'yo me quedé con el pero verdaderamente asumo la responsabilidad,muy buen profe,si no sos vago pasas,nunca te hace un quiz sin dejarte un practica,da mucho material de apoyo,yo llegué a su curso sin saber nada de algebra basica y aun así logré hacer varias cosillas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2026-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'a826994184f7fe3d9c21b4c8862c434380c8a56bc1f911e8d92156b6040feece'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Proba es un curso ya complicadillo, pero el profe da lo mejor para simplificar la materia sin bajarle en nivel tanto. Hace varios ejemplos y practicas, quices (2 antes de cada examen).Haga las practicas y estudie.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-07-28T00:00:00+00:00'::TIMESTAMPTZ, '57df0ebbc313c167af64f2272d72237b2d0499300e431a174f18ef7a0c687d38'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Excelente profesor, domina muy bien el curso e intenta dar explicaciones los más claro posible, no hace muchos ejercicios de ejemplo pero siempre esta dispuesto a brindar toda la ayuda y apoyo para entender la materia'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '8c9f1a5890dbef0d9bd2f6328d301543e7b5d09a2fa9011318211c3cc53cb1bf'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Es relativamente sencillo, no califica nada duro y explica bien y de manera clara. Aunque no da muchos ejemplos'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '0efa502bde7c7513e43bbd4200ea0617cef22c79d8f64b229e0d0c85959532e9'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'El profe explica muy bien, pero, siempre nos deja salir media hora antes por eso se hace muy pocos ejercicios con él en clases. NO DA NI UN PUNTO EXTRA.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'c778be7efaffd1a8e5496ef5299f41d6f21bb8531e28bfbb2d1ac12daca6f7fd'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Mi profesor preferido de toda la escuela de mate, recompensa el esfuerzo del estudiante y castiga la vagancia. Unicamente ayuda (y mucho) a las personas que le ponen empeño al curso, cosa que no es tan dificil con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-15T00:00:00+00:00'::TIMESTAMPTZ, '86eb0dc3f89fd0cd27f9fbcd384c146a0946b83dda96acc90a9d4dc1f6c245ce'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Buen profesor, sabe de la materia entonces la forma en la que explica y el material que brinda sirve demasiado. En los exámenes procure detallar cada paso que hace para así rascar puntos.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'bfe09f480371dcf8ce7294a19bdefbc5992fabefa00815c2eedb2afbefccb10d'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Llega a leer diapositivas a la clase, sinceramente no siento que explique tan bien pero es mejor que otros. Si tiene dudas le ayuda y califica suave'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'ba3ae8009156329a21daf9cba32c052a5b2d24e39a1cf5de136b50d194ece3c7'::TEXT, ARRAY[1057]::BIGINT[]),
    (482::BIGINT, 'Explica lo que está en el libro/material de clase, si quiere puede ir a consulta o también el profe da la opción de que le pregunten por mensaje y él responde cuando pueda, normalmente bastante rápido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1601714b9371155f10dc32f6d472be9bf788876b2f416af86b0e0e9e972e4c0c'::TEXT, ARRAY[1057]::BIGINT[]),
    (482::BIGINT, 'La explicación de la materia suele ser con los folletos del curso pero básicamente lo que explica es lo que entra en las evaluaciones del curso. Suele ser serio pero es muy buena gente, la verdad deberían de pagarle el doble porque de verdad brinda mucha ayuda hasta material para cada parcial.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '43db91af6d919dc5bb9407679a6cc64cc4e5a11f6cecb774b060692a004eb551'::TEXT, ARRAY[634]::BIGINT[]),
    (482::BIGINT, 'muy cosito y un toque barco.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'cf3d713d8bf0a5ac335d0cdec50b32fffd6e754e463b9ab99fc312dfb5018fd6'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'El mejor profe para proba. Explica bastante claro, se preocupa por que el estudiante entienda y siempre esta dispuesto a ayudar. El curso es pesado, por lo que hay que practicar bastante, sin embargo el profe lo hace más ameno!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, '9dab910d5485b748fd706d5d69cdb2aae42ba7b377b8074409f2ceefd6478c94'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'El mejor profesor para esta materia. Él es muy serio, pero se preocupa porque el estudiante entienda. Estudien desde el primer día, ya que el contenido puede ser difícil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, '285c64d71dbc858f1299feeae34428e953eb197b0186d6b73d4ba932a19b1050'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Buen profe, aunque es bastante serio califica suave'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'e4e6fa9076258ffac823c9fff119ee8d70f41672974c483953fea7a479c66b1c'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Explica muy bien y califica medio. Es muy serio y casi poco accesible, pero en consulta siempre ayuda.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f104bf20d9731887a4369acb64cf27a6f06959cefbdb3181d491cdb09e1af1da'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Buen profe. Las explicaciones pueden ser algo confusas pero siempre está dispuesto a resolver dudas. A veces ve mucha materia muy rápido, sin embargo es muy flexible con la manera de ver el contenido. Siempre busca lo mejor para el estudiante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '3b967e9914397c95a61bb8b600a6133a76a3a9f6238ce77c19a1785b8d3e8a75'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Un profesor serio y respetuoso. Que si le pone atención a sus clases él te va ayudar mucho, muy dispuesto a consultas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'de03947aec6db42c44a7fae453206cbe54911aa943bcb6420382bc7e213cb001'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'El profe es muy serio e indiferente, pero hace el curso lo más relajado posible y eso se agradece porque le queda tiempo para otras materias. Si usted ya llevo MD o no le cuesta mate es la mejor opción, de lo contrario le recomendaría a otro profe que pueda guiarlo más.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'da16eb59eeb090da1cdc3974aecb87f03588e3621d5718925c4febc9a54d1042'::TEXT, ARRAY[1018]::BIGINT[]),
    (482::BIGINT, 'Este profe es un hipócrita, no vuelvo a llevar nada con él.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9c255174992932756a15ea7de3d008a8c5cdc516eeb8cbd63e4ea9a3d74d8751'::TEXT, ARRAY[1018]::BIGINT[]),
    (482::BIGINT, 'Excelente profesor, explica bien, brinda apoyo cuando se lo necesite y está dispuesto a cualquier tipo de dudas, sin duda volvería a matricular un curso con el , calidad :D'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '27c658824f9c335387c48a1dbd7742c797801feb7bdf174b0b5bfbb32b64f182'::TEXT, ARRAY[1018]::BIGINT[]),
    (482::BIGINT, 'El profe explica bien, y siempre está dispuesto a brindar apoyo cuando se necesita'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-08-01T00:00:00+00:00'::TIMESTAMPTZ, '0ff9ab3aeec772af0ad8c7a02c40f89937ed1e37a2b1b59b188070a1db5082e2'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'El mejor profesor para está materia, clases excelentes y si usted ocupa ayuda siempre responde a las consultas. La cátedra es lo que es un asco.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ce22e6c2c0a7393bec239a715f5fb1894e804656506f223e1c3d94d9a4c3fae1'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Él es un profesor increíble, explica una materia tan compleja y abstracta como lo es Proba de una forma súper clara, pero la Cátedra es una mierda, parece que quieren quedarlo a uno. Matrícule con él y aumentan sus probabilidades de pasar.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4927830d0f8b1143261424064e16e846c68c3e96ec2f861ecdce0594ef43910e'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'El profe es muy bueno y califica suave. Lo único malo es la cátedra que fácilmente es la peor de toda la escuela de matemática. Guías incompletas, ejercicios resueltos de manera incorrecta y exámenes duros. Recomendado matricular con el tho, es lo único que salva el curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'dad27f6c80f251f69ba39dbb5033583a07cbdf1ce12a31946f2928c84a10d60f'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'El profe es un toque amargado y al ser amargado la clase puede ser un poco aburrida, pero también es muy buena gente, si las clases hubieran sido presenciales le hubiera entendido mejor. Es buen profe, se preocupa por responder las dudas de los demás, me dió tiempo de entregar una tarea después.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '21d90c7f355c2075ca49b0d56a540a8262c149ea44c54dc1028f854573130095'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'El profe es un super buen profesor, siempre busca ayudarnos y explica super bien. La catedra de proba es lo que jode el curso realmente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'e8403e8644d6866495185cd9c1a09013d666bcfe7d6acbfd21efc504dc925990'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Algo super bueno que tiene es que se toma la molestia de grabar videos extra de un tema si ve que al grupo le esta costando, lo cual se agradece mucho. A veces las clases son un poco largas o aburridas. Siempre contesta por Telegram casi de inmediato y con él uno puede sacar buenas notas si estudia.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, '202b284731e6b887a20aec60d11b493239f5995e9f242bac179acd63ef8a7032'::TEXT, ARRAY[1049, 4836]::BIGINT[]),
    (482::BIGINT, 'El curso se hace difícil porque las guías de la cátedra son muy confusas y muchos ejercicios están mal resueltos o bien no tienen solución. El profe adapta muy bien las clases a la virtualidad, una clase explica la materia y la otra la dedica sólo a resolver ejercicios. Responde rápido.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'aeae5acdc6bb07e5e5d0a941db0a4b2dd07e8e0c0a47ec33c7532e2c25ce4c29'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-09T00:00:00+00:00'::TIMESTAMPTZ, '4eacc45c50ee634d9865646b7758ddc69f7982b0b276a0594c23d8b3c6469cae'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Explica excelente y atiende cualquier consulta que se tenga. Siempre está dispuesto a ayudar. Califica a tiempo por tanto brinda retroalimentación. En general, excelente profesor y excelente persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'df7e139a39e83aae28a3c1c11ac88dfbc54a8c2197c957326820a9c4dc8fa90f'::TEXT, ARRAY[634]::BIGINT[]),
    (482::BIGINT, 'Excelente profesor. Se esfuerza por explicar de la mejor manera para que todos entiendan. Toma en cuanta la opinión de los estudiantes en cuanto a la metodología de las clases. Se adaptó muy bien a la virtualidad. Siempre está dispuesto a ayudar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '4d1a6920791fbfc1470fb5afe565c051c246f98b4fb610233ce3a3a551515739'::TEXT, ARRAY[634]::BIGINT[]),
    (482::BIGINT, 'Un excelente profesor. Por lo menos en virtualidad, el profesor se esmeró por adaptarse a esta modalidad de una excelente manera. Explica muy bien los ejercicios y la clase es bastante amena. Muy ordenado en cuanto a revisión, entrega, evaluaciones y materia del curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'd8c6064bb351a6b184f37d85ea43d3d0821521f4b6382bdc5fa63e91bce4b750'::TEXT, ARRAY[4836]::BIGINT[]),
    (482::BIGINT, 'El profe es muy buena gente y siempre trata de hacer lo mejor para que sus estudiantes entiendan y a pesar de que a veces se confundía o no sabía como resolver un ejercicio siempre trataba de buscar una solución y compartirla con nosotros. Me hubiera gustado que organizara un poco mejor las clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c371cc43bf17bae697301507def0472165992b4cac3995bb4fc4dae08d68396d'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'El profe es pura vida y siempre está dispuesto a ayudar. Solo que a veces se enreda y no puede terminar algunos ejercicios. Pero se esfuerza porque el estudiante aprenda.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ce9ac3d3ead3fdd0e44da6f7fff230204eb5546cd6af04f8954c074c9d700b5b'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'Si está aquí para compararlo con Mario, matricule con Mario sin pensarlo. Definitivamente Bryan no está capacitado para este curso, mejor que se quede en MG. Nunca organiza sus clases y si le hacen una pregunta probablemente no sepa responderla!'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-04-06T00:00:00+00:00'::TIMESTAMPTZ, '981ff3732c8d1d2059fda359fbbaee0c3ef466b471706083185667d6312ede5b'::TEXT, ARRAY[1049]::BIGINT[]),
    (482::BIGINT, 'El curso en si ya es bastante complicadito para las personas que no tienen buenas bases en matemática, el profesor explica bastante rápido y si no entiendes los ejercicios que deja como "tarea moral" tendrás que ir a la consulta PD: el tiene una letra HORRIBLE así que lo mejor es que aprendas a leer'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '9f6beea5a3eeb09a3d390ca7988d443a11d07d77bd50dc5c529d191379b24e8f'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Un profe muy bueno, pero explica muy rápido, si usted al igual que yo es de esas personas que ocupan darse su tiempo para entender un ejercicio probablemente tenga que asistir bastante a hora consulta, de igual forma es un excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '52d25c5a08996aa57f7a6d45c3fede9b57a3f1b5b1ab02567b6852a4f60d8bdd'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Es serio pero es buena nota, prepara bastante bien para los exámenes y hace videos extra explicando temas complicados. Hay que tener cierta afinidad a la matemática para entenderle porque a la hora de resolver ejercicios se "brinca" varios pasos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '0e2422dee946556d518a1e667fdf2d0efc42e2d16f63b539d04f62a9813419bf'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Muy buen profe, de hecho, el mejor profe que he tenido hasta ahora. Explica muy claro y no califica dura. A veces las clases si se pueden volver un poco largos. Es serio pero no es mala nota. En definitiva, un profe genial.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '7fc8069e6e902bdcb419405b3285b9e15706e874f67384e59d52c933a6d4f747'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '8ff7d1cf97af1b89dd046a824c6c17dc0b15485ca3ad94820d83334a88395f3f'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Excelente profesor, da material de apoyo sin que uno se lo pida, domina el uso de herramientas virtuales y sube los videos de las clases minutos despues de que fueron grabadas, en general 20/10. Además ayuda en otros cursos si es necesario!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'a0260572eb9271874466a5cd8f2f534b38787c516d3a0d27ee4dedb6937f2667'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Es un excelente profesor, explica claro los temas y siempre evacúa dudas. En las clases virtuales es super puntual a la hora de re subir las clases. Si tuviera la oportunidad volvería a matricular con él. La dificultad es notoria pero por razones del curso.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '9e0fef5f7d6103e771b26da82d9623ec80c3378f4fedb9711e1bec4620baae24'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, '747433908d6dcac1173d45fa3fa6223e9e5e4287cd16bb007314129e0a3be6ac'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, '213ca05971cc188eaf8480c49a17c07bed2888ae3d8acac3ba040e310327ab8b'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Muy buen profe,explica claramente,no se enreda y responde las dudas muy puntualmente. Para el primer semestre virtual se encontraba bien adaptado a entornos virtuales y subía todos los vídeos al canal en cuanto terminaba la clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'f5939d8d493aaea99d6ada56300b901b1ff6b223fe5652fa24169fd4425484a7'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Excelente profe, hace repaso la semana antes del exámen. Deja mucha práctica, es importante ir a hora de consulta y aclarar dudas con el.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'e249494b41699e83eab723a4ebc4bf8099ff58f80f1b06d2b33f7d15bc003f5c'::TEXT, ARRAY[2444]::BIGINT[]),
    (482::BIGINT, 'El profe explica super bien, hasta brinda material digital para estudiar en la casa si nose tomaron apuntes. Ayuda mucho al estudiante. Recomendado'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '8b9ca410020d0bfda6640acb68cac0d177a1795f9f2b3cbe73109ff2db17d331'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Excelente profesor, con instrucciones y materia clara. Ayuda bastante al estudiante siempre que él se lo pida. Deja bastantes tareas de moderada dificultad para ayudar en puntos a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-14T00:00:00+00:00'::TIMESTAMPTZ, '1c41ee80464dfed4161fa77c1f695e3d1f949d7b85745494a9825ac19b7540a0'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Explica de manera clara, sin embargo, las clases pueden parecer largas. Brinda repaso antes de cada examen, deja bastantes tareas de moderada dificultad.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '56f58b0732f662bc290713b607582e879351239f35c11d3959ba351d1092ee41'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Explica muy claro. Primero introduce la teoría y luego da algunos ejemplos. Casi no se practica en la clase pero con los ejemplos que hace ya se pueden hacer los demás ejercicios.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '315c1b6599f04f610617595b6b5469e7185a46a5caa0bc6530877f32391b7269'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Buen profe, las clases son claras y le abarca las dudas si se lo pide.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '380c92fea422dc66f1fe1986ae159cab2fa6686511076d9d9f87ad7e97e6830d'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'La verdad es un profe muy bueno, explica demaciado bien y con mucha claridad, hace como 2 quices antes de cada examen y hace centros de repaso al final'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2019-02-04T00:00:00+00:00'::TIMESTAMPTZ, '43f11e5eb6ad4beebf5f745121de6421b0b1ac3266422119817d898d7a3a7a07'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '461380424ab911b6e9c21b943b3477c210dc44e474d8f331bf440b5aee019a62'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Las clases son bastantes aburridas; sin embargo, el mae explica bastante claro!'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '55e03e2858569d28e5244040c6e82f8b01450e4cf6cb45103044a27c1ec99f10'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'El profesor se nota un poco serio, sin embargo el demasiado bueno explicando, califica normal, deja practica y se interesa en el aprendizaje de los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'cd85a21f157a187c9cf5cacca3870d91c4682c12b4a34e6fb4fb60f04fa58fa9'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Muy buen profe, no dude en matricular con el. Explica claro, deja ejercicios para la casa de cada tema, de igual forma se sabe que la practica es independiente. Se preocupa para que el estudiante aprenda, da clases de repaso. Las asignaciones se dividen en quices, tareas y trabajos en clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'fcdc5fb717f8eeff02cb2249f7f6d2563211fd207970f25390c868b6e361e3e1'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Es muy buena gente y es divertido cuando se le agarra confianza, un poco difícil, si no le ponen se van a quedar...'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'f8e1ef195f037976494b396fdbc4b368b564787c65e8fd5c1d96b55399ec904e'::TEXT, ARRAY[1018, 563]::BIGINT[]),
    (482::BIGINT, 'El profe se ve súper serio pero se preocupa por el estudiante y está siempre dispuesto a ayudar al que se haya esforzado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a11d4714e11a7dcadd4d80b12bbde924574c9cf871607014deeb1ccda6eed8ae'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'Excelente profe de mate. Es super claro y siempre está dispuesto a despejar dudas. El unico problema es que no deja muchas practicas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a9bc611d07a705542c00ce8347a8a254422b25856c4b6d4788fa8dad81c9941f'::TEXT, ARRAY[1018]::BIGINT[]),
    (482::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '9f9e246e857f92648f3cfb2157a922e06d0ece24535a426d192990f37889dfd5'::TEXT, ARRAY[2444]::BIGINT[]),
    (482::BIGINT, 'Tiene cara de serio pero es muy buena nota. Explica super claro y siempre está dispuesto a despejar dudas. Lo único malo es que no deja mucha práctica excepto por las que deja antes de un examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'caaf14a9bb9b34ac3c212c678f90b644eb2113052dbe6c2a7730a8383a187f21'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'usted lo ve y el mae esta bien wiso pero es relativamente bueno va a lo que va a dar la clase pero ayuda con un 20 % practicamente regalado se lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'daab0979c2771d4e9ecd5c0f9a822ecef0146cba6f431ce3b660621b2872b0f7'::TEXT, ARRAY[1653]::BIGINT[]),
    (482::BIGINT, 'Las explicaciones por lo general son claras. Siempre anda de mal humor parece que no le gusta dar clases. Definitivamente hay que estudiar bastante por aparte, deja practicas de examen que muy pocas veces se ven en clase y son muy fáciles comparado con lo que entra en el examen.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, '15781bb0e4d4bc3c6214f8423cb334c1a09d67ebce57306dfa5ed1513e2d8d92'::TEXT, ARRAY[2444]::BIGINT[]),
    (482::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-30T00:00:00+00:00'::TIMESTAMPTZ, '8e1ce71fbbfa1f72a128442eb61b2ae70e1ecf23d1cc42fe8355c20e26ec6b98'::TEXT, ARRAY[605]::BIGINT[]),
    (482::BIGINT, 'Bastante teórico lo que quiere decir que explica el por qué de muchas cosas, no califica muy duro, deja tareas y quices. Volvería a matricular un curso con el.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'c922a0ff5e58fd29472c8aad084993d03f4f872618f33c31d7a4dad5ebacd7ab'::TEXT, ARRAY[605]::BIGINT[]),
    (482::BIGINT, 'Muy teórico, explica lo necesario, es necesario estudiar bastante por aparte y despejar dudas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, '0fa7656102de07c8d58e1ff8858b6db337f08d12f1c6a8ba8aeaac2bdb9cdb2c'::TEXT, ARRAY[605]::BIGINT[]),
    (482::BIGINT, 'Demasiado teórico, no explica tan bien'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '486ed11c1d90902b42ea71e266e7a2711df101861ccbb78767cf5d3e0aa42a4b'::TEXT, ARRAY[605]::BIGINT[]),
    (482::BIGINT, 'Da demasiada teoría, usa los ejemplos más fáciles. Si le preguntás algo mientras está dando la clase, se molesta y responde de mala gana. No meta con él.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-23T00:00:00+00:00'::TIMESTAMPTZ, '8deab72829eee63f7935bf076869cc1ac8b909c9ec1461cc21780eaec0f522de'::TEXT, ARRAY[605]::BIGINT[]),
    (482::BIGINT, 'Da demasiada teoría que no es necesaria para el curso, explica ejercicios muy fáciles en comparación al nivel del examen y deja los más difíciles para la casa, los cuales nunca resuelve y se debe tomar mucho tiempo para estudiar fuera de la clase, sin embargo siempre ayuda si se le pide'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3a2143548e42dd9c292b3972d264ebf101c771c9b08d4e4cd289e8750f2dbd1c'::TEXT, ARRAY[605]::BIGINT[]),
    (482::BIGINT, 'El profe es nuevo pero explica bien, da bastante teoría y deja ejercicios para realizar en la casa. No deja tareas pero hace varios quices y califica trabajo en clase como quices (si va y por lo menos hace algo ya tiene el 100 en esa evaluación)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a7f150b371755ec4509e11be76b2abda24aadf8b6341c15b817a9a3962eb6329'::TEXT, ARRAY[563]::BIGINT[]),
    (482::BIGINT, 'No muestra un buen dominio de la materia ni un interés por darla. Únicamente transcribe el libro que usamos, a la pizarra, sin esforzarse en dar explicaciones propias.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '5ebce9a796190a58b53d6c0896f2f5c39df996f4aa9aed07afc85945141f9a46'::TEXT, ARRAY[1018]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
